```python
_TRUE = True
_FALSE = False
_MISSING = object()


class _Ctx:
    """Evaluation context: a row (WHERE) or a group (HAVING / SELECT)."""

    __slots__ = ("row", "cols", "rows", "cache")


def _cmp3(op, a, b):
    """SQL three-valued comparison: NULL on either side gives UNKNOWN."""
    if a is None or b is None:
        return None
    if op == "=":
        return a == b
    if op == "!=":
        return a != b
    if op == "<":
        return a < b
    if op == "<=":
        return a <= b
    if op == ">":
        return a > b
    return a >= b


def _and3(a, b):
    if a is _FALSE or b is _FALSE:
        return _FALSE
    if a is None or b is None:
        return None
    return _TRUE


def _aggregate(func, arg, group_rows):
    """SQL aggregate over one group; NULLs are ignored."""
    if func == "count":
        if arg == "*":
            return len(group_rows)
        n = 0
        for row in group_rows:
            if row[arg] is not None:
                n += 1
        return n
    if func == "count_distinct":
        seen = set()
        for row in group_rows:
            v = row[arg]
            if v is not None:
                seen.add(v)
        return len(seen)
    if func == "sum":
        total = 0
        found = False
        for row in group_rows:
            v = row[arg]
            if v is not None:
                total += v
                found = True
        return total if found else None
    if func == "avg":
        total = 0
        n = 0
        for row in group_rows:
            v = row[arg]
            if v is not None:
                total += v
                n += 1
        if n == 0:
            return None
        return total // n  # floor division: rounds down, also for negative sums
    # min / max
    want_min = func == "min"
    best = None
    found = False
    for row in group_rows:
        v = row[arg]
        if v is None:
            continue
        if not found:
            best = v
            found = True
        elif want_min:
            if v < best:
                best = v
        else:
            if v > best:
                best = v
    return best if found else None


def _operand(opnd, ctx):
    kind = opnd[0]
    if kind == "col":
        if ctx.row is not None:
            return ctx.row[opnd[1]]
        cols = ctx.cols
        if cols is not None:
            value = cols.get(opnd[1], _MISSING)
            if value is not _MISSING:
                return value
        group_rows = ctx.rows
        if group_rows:
            return group_rows[0].get(opnd[1])
        return None
    if kind == "val":
        return opnd[1]
    # ["agg", func, arg]  (cached per group)
    key = (opnd[1], opnd[2])
    cache = ctx.cache
    value = cache.get(key, _MISSING)
    if value is not _MISSING:
        return value
    value = _aggregate(opnd[1], opnd[2], ctx.rows)
    cache[key] = value
    return value


def _resolve(x, ctx):
    if isinstance(x, (list, tuple)):
        return _operand(x, ctx)
    return x


def _eval(cond, ctx):
    op = cond[0]
    if op == "and":
        a = _eval(cond[1], ctx)
        if a is _FALSE:
            return _FALSE
        b = _eval(cond[2], ctx)
        if b is _FALSE:
            return _FALSE
        if a is None or b is None:
            return None
        return _TRUE
    if op == "or":
        a = _eval(cond[1], ctx)
        if a is _TRUE:
            return _TRUE
        b = _eval(cond[2], ctx)
        if b is _TRUE:
            return _TRUE
        if a is None or b is None:
            return None
        return _FALSE
    if op == "not":
        a = _eval(cond[1], ctx)
        if a is None:
            return None
        return _FALSE if a is _TRUE else _TRUE
    if op == "is_null":
        return _resolve(cond[1], ctx) is None
    if op == "in":
        v = _resolve(cond[1], ctx)
        values = cond[2]
        if not values:
            return _FALSE
        if v is None:
            return None
        has_null = False
        for e in values:
            if e is None:
                has_null = True
            elif v == e:
                return _TRUE
        if has_null:
            return None
        return _FALSE
    if op == "between":
        v = _resolve(cond[1], ctx)
        lo = _resolve(cond[2], ctx)
        hi = _resolve(cond[3], ctx)
        return _and3(_cmp3(">=", v, lo), _cmp3("<=", v, hi))
    return _cmp3(op, _resolve(cond[1], ctx), _resolve(cond[2], ctx))


def _filter(rows, where):
    if where is None:
        return list(rows)
    ctx = _Ctx()
    ctx.row = None
    ctx.cols = None
    ctx.rows = None
    ctx.cache = {}
    passing = []
    for row in rows:
        ctx.row = row
        if _eval(where, ctx) is _TRUE:
            passing.append(row)
    return passing


def run_query(rows: list[dict], query: dict) -> list[dict]:
    # ---- select specification ----
    spec = []  # (output key, is_aggregate, payload)
    plain_cols = []
    has_agg = False
    for item in query["select"]:
        if isinstance(item, str):
            if item == "*":
                spec.append(("count(*)", _TRUE, ("count", "*")))
                has_agg = True
            else:
                spec.append((item, _FALSE, item))
                plain_cols.append(item)
        else:
            func, arg = item[0], item[1]
            spec.append(("%s(%s)" % (func, arg), _TRUE, (func, arg)))
            has_agg = True

    group_by = query.get("group_by") or ()
    having = query.get("having")
    grouped = bool(group_by) or has_agg

    # ---- where ----
    passing = _filter(rows, query.get("where"))

    if not grouped:
        # plain query: one output row per passing row
        outputs = []
        for row in passing:
            out = {}
            for key, is_aggregate, payload in spec:
                out[key] = row[payload]
            outputs.append(out)
    else:
        # ---- grouping: group_by plus every plain selected column ----
        key_cols = list(group_by)
        known = set(key_cols)
        for col in plain_cols:
            if col not in known:
                key_cols.append(col)
                known.add(col)

        groups = {}
        if key_cols:
            if len(key_cols) == 1:
                first = key_cols[0]
                for row in passing:
                    k = (row[first],)
                    bucket = groups.get(k)
                    if bucket is None:
                        groups[k] = [row]
                    else:
                        bucket.append(row)
            else:
                for row in passing:
                    k = tuple(row[c] for c in key_cols)
                    bucket = groups.get(k)
                    if bucket is None:
                        groups[k] = [row]
                    else:
                        bucket.append(row)
        else:
            groups[()] = passing  # single group, even when no row passed

        build_cols = bool(plain_cols) or having is not None
        ctx = _Ctx()
        ctx.row = None
        ctx.cols = None
        outputs = []
        for k, group_rows in groups.items():
            if build_cols:
                ctx.cols = dict(zip(key_cols, k))
            ctx.rows = group_rows
            ctx.cache = {}
            # ---- having ----
            if having is not None and _eval(having, ctx) is not _TRUE:
                continue
            # ---- select ----
            out = {}
            for key, is_aggregate, payload in spec:
                if is_aggregate:
                    out[key] = _operand(("agg", payload[0], payload[1]), ctx)
                else:
                    out[key] = _operand(("col", payload), ctx)
            outputs.append(out)

    # ---- distinct ----
    if query.get("distinct"):
        out_keys = [key for key, _flag, _payload in spec]
        seen = set()
        unique = []
        for out in outputs:
            sig = tuple(out[k] for k in out_keys)
            if sig in seen:
                continue
            seen.add(sig)
            unique.append(out)
        outputs = unique

    # ---- order_by (stable, applied from the last key to the first) ----
    order = query.get("order_by")
    if order:
        for entry in reversed(order):
            key = entry[0]
            direction = entry[1] if len(entry) > 1 else "asc"
            nulls = entry[2] if len(entry) > 2 else None
            desc = direction == "desc"
            if nulls is None:
                nulls_first = not desc  # NULLs first for asc, last for desc
            else:
                nulls_first = nulls == "first"
            if nulls_first:
                none_flag, val_flag = (0, 1) if not desc else (1, 0)
            else:
                none_flag, val_flag = (1, 0) if not desc else (0, 1)
            outputs.sort(
                key=lambda r, k=key, nf=none_flag, vf=val_flag: (
                    (nf, 0) if r[k] is None else (vf, r[k])
                ),
                reverse=desc,
            )

    # ---- offset / limit ----
    offset = query.get("offset")
    if offset:
        outputs = outputs[offset:]
    limit = query.get("limit")
    if limit is not None:
        outputs = outputs[:limit]

    return outputs
